.demo-code pre,.demo-install {
  white-space: pre;
  overflow: auto;
  direction: ltr;
  text-align: left;
  padding: 1rem;
  font-size: .8125rem;
  line-height: 1.6;
  border-radius: .5rem;
  background: var(--ehs-bg);
  color: var(--ehs-text);
}

.demo-cell {
  padding: .85rem;
  background: var(--ehs-primary-soft);
  border: 1px solid var(--ehs-border);
  border-radius: .35rem;
  color: var(--ehs-primary);
  font: .8125rem/1.5 monospace;
  text-align: center;
}

.demo-swatches {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(120px,1fr));
  gap: .75rem;
}

.demo-swatch {
  padding: 2rem .75rem .75rem;
  border-radius: .5rem;
  font-size: .8125rem;
}

.demo-class-results {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(240px,1fr));
  gap: .4rem;
  max-height: 22rem;
  overflow: auto;
  margin-block-start: 1rem;
}

.demo-class-results code {
  padding: .4rem .6rem;
  background: var(--ehs-bg);
  border-radius: .25rem;
  font-size: .75rem;
  overflow-wrap: anywhere;
}

.demo-footer {
  border-block-start: 1px solid var(--ehs-border);
  padding-block-start: 2rem;
  margin-block-start: 3rem;
  color: var(--ehs-muted);
  font-size: .875rem;
}

.demo-skip {
  position: absolute;
  top: -100px;
}

.demo-skip:focus {
  top: 1rem;
  inset-inline-start: 1rem;
  z-index: 200;
  background: var(--ehs-surface);
  padding: 1rem;
}

@media(max-width: 991px) {
  .demo-layout {
    grid-template-columns: 1fr;
  }
}

@media(max-width: 991px) {
  .demo-side {
    position: static;
    height: auto;
    padding: 1rem;
    border-inline-end: 0;
    border-block-end: 1px solid var(--ehs-border);
  }
}

@media(max-width: 991px) {
  .demo-side small {
    margin-block-end: .75rem;
  }
}

@media(max-width: 991px) {
  .demo-side nav {
    display: flex;
    gap: .25rem;
    overflow-x: auto;
  }
}

@media(max-width: 991px) {
  .demo-side a {
    white-space: nowrap;
  }
}

@media(max-width: 991px) {
  .demo-main {
    padding-block-start: 1rem;
  }
}

@media print {
  .demo-side,.demo-top,.demo-code {
    display: none;
  }
}

@media print {
  .demo-layout {
    display: block;
  }
}

@media print {
  .demo-main {
    padding: 0;
  }
}

.demo-side {
  background: var(--md-sys-color-surface-container-low);
}

.demo-side a {
  border-radius: 999px;
}

.demo-example {
  background: var(--md-sys-color-surface);
  border-radius: 24px;
}

.demo-hero {
  border: 0;
  background: var(--md-sys-color-primary-container);
  color: var(--md-sys-color-on-primary-container);
  border-radius: 28px;
  padding: clamp(1.25rem,4vw,3rem);
}

.demo-hero .demo-lead,.demo-hero .demo-eyebrow {
  color: var(--md-sys-color-on-primary-container);
}

.demo-hero .text-primary {
  color: inherit !important;
}

.demo-brand {
  letter-spacing: -.025em;
}

.demo-install,.demo-code pre {
  background: var(--md-sys-color-surface-container-low);
}

.demo-swatch {
  border-radius: 16px;
}

.demo-main.md3-app-content {
  margin: .5rem;
  padding: 1.5rem clamp(1rem,3vw,3rem) 4rem;
  border-radius: 28px;
  background: var(--md-sys-color-surface);
}

.md3-app-shell {
  background: var(--md-sys-color-surface-container);
}

@media print {
  .md3-navigation-rail,nav.md3-navigation-drawer,.md3-navigation-bar-compact {
    display: none !important;
  }
}

@media print {
  .md3-app-shell {
    display: block;
  }
}

